"""Batch ENDOKRIN, GIZI & METABOLIK: DM tipe 1, hipoglikemia, MEP, defisiensi vitamin, defisiensi mineral, dislipidemia, hiperurisemia, obesitas."""
from lib import C, CX, D, F, PF, T, NT, SY, W, X, REF_PPK

SYS = "Endokrin & metabolik"
REF_DM = [REF_PPK, "PERKENI. Pedoman Pengelolaan dan Pencegahan Diabetes Melitus Tipe 2 Dewasa di Indonesia (2021)", "IDAI. Konsensus Nasional Pengelolaan DM Tipe 1 (2017)"]
